 */
returnData(mimeSvc, data) {
  let proto = null;
  const ct = this.extractContentType(data);
  if (ct && ct.search(/multipart\/signed/i) >= 0) {
    proto = lazy.EnigmailMime.getProtocol(ct);
  }

